ransform: uppercase;\\n            position: absolute;\\n            left: 50%;\\n            top: 50%;\\n            -webkit-transform: translate(-50%, -50%);\\n            -ms-transform: translate(-50%, -50%);\\n            transform: translate(-50%, -50%);\\n        }\\n\\n        .notfound .notfound-404 h2 {\\n            font-family: \'Montserrat\', sans-serif;\\n            font-size: 28px;\\n            font-weight: 400;\\n            text-transform: uppercase;\\n            color: #211b19;\\n            background: #fff;\\n            padding: 10px 5px;\\n            margin: auto;\\n            display: inline-block;\\n            position: absolute;\\n            bottom: 0px;\\n            left: 0;\\n            right: 0;\\n        }\\n\\n        .notfound .notfound-404 h1:after,\\n        .notfound .notfound-404 h1:before,\\n        .notfound .notfound-404 h2:after,\\n        .notfound .notfound-404 h2:before {\\n            display: none;\\n        }\\n\\n        .notfound a {\\n            font-family: \'Montserrat\', sans-serif;\\n            display: inline-block;\\n            font-weight: 700;\\n            text-decoration: none;\\n            color: #fff;\\n            text-transform: uppercase;\\n            padding: 13px 23px;\\n            background: #ff6300;\\n            font-size: 18px;\\n            -webkit-transition: 0.2s all;\\n            transition: 0.2s all;\\n        }\\n\\n        .notfound a:hover {\\n            color: #ff6300;\\n            background: #211b19;\\n        }\\n\\n        @media  only screen and (max-width: 767px) {\\n            .notfound .notfound-404 h1 {\\n                font-size: 148px;\\n            }\\n        }\\n\\n        @media  only screen and (max-width: 480px) {\\n            .notfound .notfound-404 {\\n                height: 148px;\\n                margin: 0px auto 10px;\\n            }\\n\\n            .notfound .notfound-404 h1 {\\n                font-size: 86px;\\n            }\\n\\n            .notfound .notfound-404 h2 {\\n                font-size: 16px;\\n            }\\n\\n            .notfound a {\\n                padding: 7px 15px;\\n                font-size: 14px;\\n            }\\n        }\\n    <\\/style>\\n    <script>\\n        var locale = \'en\';\\n    <\\/script>\\n\\n    <script src=\\\"https:\\/\\/www.fwunlock.net\\/js\\/app.js?v=1.0.61\\\" type=\\\"text\\/javascript\\\"><\\/script>\\n<script type=\\\"text\\/javascript\\\">\\n    fx.rates = {\\\"USD\\\":1,\\\"JOD\\\":0.709,\\\"SDG\\\":\\\"600\\\",\\\"SAR\\\":\\\"3.75\\\",\\\"TRY\\\":\\\"0.033\\\",\\\"AED\\\":\\\"3.67\\\",\\\"EUR\\\":\\\"0.93\\\",\\\"MAD\\\":\\\"10.00\\\",\\\"KWD\\\":\\\"0.31\\\",\\\"IQD\\\":\\\"1310.00\\\",\\\"EGP\\\":47.75540303};\\n    var defaultCurrency = \'USD\';\\n    var currency = \'USD\';\\n    var timezone = jstz.determine();\\n\\n    \\/\\/ Modal focus fix\\n    $.fn.modal.Constructor.prototype.enforceFocus = function () {\\n    };\\n\\n    \\/\\/ Dropdown opener fix\\n    $(document.body).on(\'click\', \'[data-toggle=dropdown]\', function () {\\n        var dropmenu = $(this).next(\'.dropdown-menu\');\\n\\n        if (dropmenu.length == 0) {\\n            return;\\n        }\\n\\n        dropmenu.css({\\n            visibility: \'hidden\',\\n            display: \'block\'\\n        });\\n\\n        let containerInnerHeight;\\n        let modalBodyOffset = $(\'.modal-body\').offset();\\n        if ($(window).height() > 600 && modalBodyOffset != undefined) {\\n            containerInnerHeight = $(\'.modal-body\').outerHeight() + modalBodyOffset.top;\\n        } else {\\n            containerInnerHeight = $(window).innerHeight();\\n        }\\n\\n        \\/\\/ Determine whether bottom of menu will be below window at current scroll position\\n        if (dropmenu.offset().top + dropmenu.outerHeight() > containerInnerHeight) {\\n            dropmenu.parent().addClass(\'dropup\');\\n        }\\n\\n        \\/\\/ Return dropdown menu to fully hidden state\\n        dropmenu.removeAttr(\'style\');\\n    });\\n\\n    $(document).on(\'click\', function () {\\n        \\/\\/ Necessary to remove class each time so we don\'t unwantedly use dropup\'s offset top\\n        $(\'.dropup\').removeClass(\'dropup\');\\n    });\\n\\n    \\/\\/ Select2 defaults\\n    $.fn.select2.defaults.set(\\\"width\\\", \\\"100%\\\");\\n\\n    function initSelect(obj, force) {\\n\\n        let options = {\\n            theme: \\\"bootstrap\\\",\\n            placeholder: \'Choose\',\\n            language: {\\n                noResults: function () {\\n                    return \'No results found\';\\n                },\\n                searching: function () {\\n                    return \'Searching...\';\\n                }\\n            },\\n            allowClear: true\\n        }\\n\\n        if (obj.attr(\'data-source\') != undefined) {\\n            options.ajax = {\\n                delay: 250,\\n                url: obj.attr(\'data-source\'),\\n                dataType: \'json\',\\n                data: function (params) {\\n                    let query = {\\n                        search: params.term,\\n                        page: params.page || 1\\n                    }\\n\\n                    return query;\\n                },\\n                processResults: function (data, params) {\\n                    return {\\n                        results: data.data,\\n                    };\\n                }\\n            };\\n\\n            options.templateSelection = function (option) {\\n                let html = option.html;\\n                return html == undefined ? option.text : $(\'<span>\' + html + \'<\\/span>\');\\n            }\\n\\n            options.templateResult = function (option) {\\n                let html = option.html;\\n                return html == undefined ? option.text : $(\'<span>\' + html + \'<\\/span>\');\\n            }\\n\\n        } else {\\n\\n            options.templateSelection = function (option) {\\n                let html = $(option.element).attr(\'data-html\');\\n                return html == undefined ? option.text : $(\'<span>\' + html + \'<\\/span>\');\\n            }\\n\\n            options.templateResult = function (option) {\\n                let html = $(option.element).attr(\'data-html\');\\n                return html == undefined ? option.text : $(\'<span>\' + html + \'<\\/span>\');\\n            }\\n        }\\n\\n        if (!obj.data(\'select2\') || force) {\\n            obj.select2(options);\\n        }\\n    }\\n\\n    function initSelects(force, selector) {\\n        if (selector) {\\n            initSelect($(selector), force);\\n        } else {\\n            $(\'select.form-control\').each(function (index, obj) {\\n                initSelect($(obj), force);\\n            });\\n        }\\n    }\\n\\n    \\/\\/ Search in list\\n    (function ($) {\\n        $.fn.extend({\\n            searchInList: function (options) {\\n                var defaults = {\\n                    searchBox: \'#search\',\\n                    titles: \'.searchable\',\\n                    item: \'.item\',\\n                    groups: null,\\n                    groupTitles: \'.title\',\\n                    messageBox: \'.message\',\\n                    noResult: \'<div class=\\\"alert alert-message-danger\\\">No results found<\\/div>\'\\n                };\\n\\n                var options = $.extend(defaults, options);\\n                this.each(function () {\\n                    var o = options;\\n                    var obj = $(this);\\n                    $(o.searchBox).keyup(function () {\\n                        term = $(this).val().replace(\\/\\\\\\\\\\/g, \\\"newchar\\\");\\n                        if (term.length >= 1) {\\n                            $(o.titles, obj).each(function () {\\n                                text = $(this).text();\\n                                if (text.match(RegExp(term, \'i\'))) {\\n                                    $(this).closest(o.item).removeClass(\'x-hidden\').addClass(\'block\');\\n                                } else {\\n                                    $(this).closest(o.item).addClass(\'x-hidden\').removeClass(\'block\');\\n                                }\\n                            });\\n                        } else {\\n                            $(o.item, obj).removeClass(\'x-hidden\').addClass(\'block\');\\n                        }\\n\\n                        if (o.groups) {\\n                            $(o.groups).each(function () {\\n                                if ($(this).find(\'.block\').not(o.groupTitles).length == \'0\') {\\n                                    $(this).addClass(\'x-hidden\');\\n                                } else {\\n                                    $(this).removeClass(\'x-hidden\');\\n                                }\\n                            });\\n\\n                            if ($(o.groups).find(\'.block\').not(o.groupTitles).length == \'0\') {\\n                                $(o.messageBox).html(o.noResult);\\n                            } else {\\n                                $(o.messageBox).empty();\\n                            }\\n                        } else {\\n                            if ($(obj).find(\'.block\').not(o.groupTitles).length == \'0\') {\\n                                $(o.messageBox).html(o.noResult);\\n                            } else {\\n                                $(o.messageBox).empty();\\n                            }\\n                        }\\n                    });\\n                });\\n            }\\n        });\\n    })(jQuery);\\n\\n    \\/\\/ CSRF setup\\n    $(document).ready(function () {\\n        $.ajaxSetup({\\n            headers: {\\n                \'X-CSRF-TOKEN\': \'\',\\n                \'Accept\': \'application\\/json\'\\n            }\\n        });\\n        $.ajax({\\n            type: \'POST\',\\n            url: \'https:\\/\\/www.fwunlock.net\\/timezone\',\\n            data: \'timezone=\' + timezone.name()\\n        });\\n        initSelects();\\n    });\\n\\n    \\/\\/ Daterangepicker\\n    var daterangepickerOptions = {\\n        ranges: {\\n            \'Today\': [moment(), moment()],\\n            \'Yesterday\': [moment().subtract(1, \'days\'), moment()],\\n            \'Last 7 days\': [moment().subtract(6, \'days\'), moment()],\\n            \'Last 30 days\': [moment().subtract(29, \'days\'), moment()],\\n            \'This month\': [moment().startOf(\'month\'), moment().endOf(\'month\')],\\n            \'Last month\': [moment().subtract(1, \'month\').startOf(\'month\'), moment().subtract(1, \'month\').endOf(\'month\')],\\n            \'Show all\': [null, null]\\n        },\\n        locale: {\\n            format: \\\"YY-MM-DD\\\",\\n            separator: \\\" - \\\",\\n            applyLabel: \'Apply\',\\n            cancelLabel: \'Cancel\',\\n            fromLabel: \'From\',\\n            toLabel: \'To\',\\n            customRangeLabel: \'Custom\',\\n            weekLabel: \'W\',\\n            daysOfWeek: [\\n                \'Su\',\\n                \'Mo\',\\n                \'Tu\',\\n                \'We\',\\n                \'Th\',\\n                \'Fr\',\\n                \'Sa\'\\n            ],\\n            monthNames: [\\n                \'January\',\\n                \'February\',\\n                \'March\',\\n                \'April\',\\n                \'May\',\\n                \'June\',\\n                \'July\',\\n                \'August\',\\n                \'September\',\\n                \'October\',\\n                \'November\',\\n                \'December\'\\n            ],\\n            firstDay: 1\\n        },\\n        linkedCalendars: false,\\n        autoUpdateInput: false,\\n        showDropdowns: true\\n    };\\n\\n    function cb(start, end, label) {\\n        let selector = $(this.element[0]);\\n        if (start._isValid && end._isValid) {\\n            selector.val(start.format(\'YY-MM-DD\') + \' - \' + end.format(\'YY-MM-DD\')).change();\\n        } else {\\n            selector.data(\'daterangepicker\').remove();\\n            selector.val(label);\\n            selector.daterangepicker(daterangepickerOptions, cb).change();\\n        }\\n    }\\n\\n    \\/\\/ Datatables\\n    var refreshInterval;\\n\\n    function setAutorefresh(dt, timing, label) {\\n        if (timing > 0) {\\n            refreshInterval = setInterval(function () {\\n                dt.ajax.reload(null, false);\\n            }, timing);\\n            $(\'.reload-group\').html(label);\\n        } else {\\n            clearInterval(refreshInterval);\\n            $(\'.reload-group\').html(label);\\n        }\\n        dt.ajax.reload(null, false);\\n        $.ajax({\\n            type: \\\"GET\\\",\\n            url: \'https:\\/\\/www.fwunlock.net\\/user\\/refresh-interval\',\\n            data: \'interval=\' + timing\\n        });\\n    }\\n\\n    function updateNotifications() {\\n            }\\n\\n    function addTableFilter(table, columnSelector) {\\n        if (columnSelector != undefined && columnSelector.attr(\'id\') != undefined && columnSelector.attr(\'data-column-index\') != undefined) {\\n\\n            let column = table.DataTable().column(columnSelector.attr(\'data-column-index\'));\\n\\n            if (column.visible() !== true || $(column.header()).children(\'select\').data(\'select2\')) {\\n                return;\\n            }\\n\\n            let data = window[columnSelector.attr(\'id\') + \'_data\'];\\n\\n            if (data != undefined) {\\n\\n                if (data == \'daterange\') {\\n\\n                    let label = columnSelector.text();\\n                    let range = $(\'<input class=\\\"form-control d-inline-flex\\\" autocomplete=\\\"off\\\">\')\\n                        .appendTo($(column.header()).empty())\\n                        .daterangepicker(daterangepickerOptions, cb)\\n                        .on(\'change\', function () {\\n                            let val = $.fn.dataTable.util.escapeRegex($(range).val());\\n                            column.search(val ? val : \'\', true, false).draw();\\n                        }).val(label);\\n\\n                } else if (data == \'search\') {\\n\\n                    let search = $(\'<input class=\\\"form-control d-inline-flex\\\" placeholder=\\\"\' + columnSelector.text() + \'\\\">\')\\n                        .appendTo($(column.header()).empty())\\n                        .on(\'click\', function (e) {\\n                            e.stopPropagation();\\n                        })\\n                        .on(\'keyup\', function () {\\n                            let val = $.fn.dataTable.util.escapeRegex($(search).val());\\n                            column.search(val ? \'^\' + val + \'$\' : \'\', true, false).draw();\\n                        });\\n\\n                } else if (data.ajax != undefined) {\\n\\n                    let select = $(\'<select class=\\\"form-control d-inline-flex\\\" data-placeholder=\\\"\' + columnSelector.text() +\\n                        \'\\\" data-source=\\\"\' + data.ajax + \'\\\"><option value=\\\"\\\"><\\/option><\\/select>\')\\n                        .appendTo($(column.header()).empty())\\n                        .on(\'change\', function () {\\n                            let val = $.fn.dataTable.util.escapeRegex($(select).val());\\n                            column.search(val ? \'^\' + val + \'$\' : \'\', true, false).draw();\\n                        });\\n\\n                    initSelects();\\n\\n                } else {\\n\\n                    let select = $(\'<select class=\\\"form-control d-inline-flex\\\" data-placeholder=\\\"\' + columnSelector.text() +\\n                        \'\\\"><option value=\\\"\\\"><\\/option><\\/select>\')\\n                        .appendTo($(column.header()).empty())\\n                        .on(\'change\', function () {\\n                            let val = $.fn.dataTable.util.escapeRegex($(select).val());\\n                            column.search(val ? \'^\' + val + \'$\' : \'\', true, false).draw();\\n                        });\\n\\n                    $.each(data, function (d, j) {\\n                        if (column.search() === \'^\' + d + \'$\') {\\n                            select.append(\'<option value=\\\"\' + d + \'\\\" selected=\\\"selected\\\">\' + j + \'<\\/option>\');\\n                        } else {\\n                            select.append(\'<option value=\\\"\' + d + \'\\\">\' + j + \'<\\/option>\');\\n                        }\\n                    });\\n\\n                    initSelects();\\n                }\\n            }\\n        }\\n    }\\n\\n    \\/\\/ DataTables setup\\n    (function ($, DataTable) {\\n        $.extend(true, DataTable.defaults, {\\n            language: {\\n                emptyTable: \\\"<span>No data available<\\/span>\\\",\\n                info: \\\"Showing _START_ to _END_ of _TOTAL_ items\\\",\\n                infoEmpty: \\\"Showing 0 to 0 of 0 items\\\",\\n                infoFiltered: \\\"(Filtered from _MAX_ total items)\\\",\\n                infoPostFix: \\\"\\\",\\n                infoThousands: \\\",\\\",\\n                lengthMenu: \\\"Show _MENU_ items\\\",\\n                loadingRecords: \\\"Loading...\\\",\\n                processing: \\\"<div class=\'table-loading text-center\'><img style=\'width: 50px; height: 50px;\' src=\'\\/images\\/loading-grey.svg\'><\\/div>\\\",\\n                search: \\\"Search:\\\",\\n                zeroRecords: \\\"No results found\\\",\\n                paginate: {\\n                    first: \\\"First\\\",\\n                    last: \\\"Last\\\",\\n                    next: \\\"Next\\\",\\n                    previous: \\\"Previous\\\"\\n                },\\n                aria: {\\n                    sortAscending: \\\": Sort ascending\\\",\\n                    sortDescending: \\\": Sort descending\\\"\\n                },\\n                select: {\\n                    rows: {\\n                        _: \\\"\\\",\\n                        0: \\\"\\\",\\n                        1: \\\"\\\"\\n                    }\\n                },\\n                buttons: {\\n                    pageLength: \\\"Show %d items&nbsp;<span class=\'caret\'\\/>\\\"\\n                }\\n            }\\n        });\\n    })(jQuery, jQuery.fn.dataTable);\\n\\n    (function ($, DataTable) {\\n        \\\"use strict\\\";\\n\\n        DataTable.ext.buttons.export = {\\n            extend: \'collection\',\\n\\n            className: \'buttons-export\',\\n\\n            text: function (dt) {\\n                return \'<i class=\\\"fa fa-download\\\"><\\/i> Export&nbsp;<span class=\\\"caret\\\"\\/>\';\\n            },\\n\\n            autoClose: true,\\n        };\\n\\n        DataTable.ext.buttons.reset = {\\n            className: \'buttons-reset\',\\n\\n            text: function (dt) {\\n                return \'<i class=\\\"fa fa-undo\\\"><\\/i> Reset columns\';\\n            },\\n\\n            action: function (e, dt, button, config) {\\n                dt.colReorder.reset();\\n                dt.columns(config.show).visible(true);\\n                dt.ajax.reload(null, false);\\n            }\\n        };\\n\\n        DataTable.ext.buttons.reload = {\\n            extend: \'collection\',\\n\\n            className: \'buttons-reload\',\\n\\n            text: function (dt) {\\n                return \'<i class=\\\"fa fa-refresh\\\"><\\/i> Reload&nbsp;<span class=\\\"reload-group\\\">\' +\\n                                                                                    \'<\\/span>&nbsp;<span class=\\\"caret\\\"\\/>\';\\n            },\\n\\n            autoClose: true,\\n\\n            buttons: [\'reloadmanual\', \'reload1minute\', \'reload5minutes\', \'reload10minutes\', \'reload30minutes\']\\n        };\\n\\n        DataTable.ext.buttons.reloadmanual = {\\n\\n            text: function (dt) {\\n                return \'Manual\';\\n            },\\n\\n            action: function (e, dt, button, config) {\\n                setAutorefresh(dt, 0, \'\');\\n            }\\n        };\\n\\n        DataTable.ext.buttons.reload1minute = {\\n\\n            text: function (dt) {\\n                return \'Every 1 minute\';\\n            },\\n\\n            action: function (e, dt, button, config) {\\n                setAutorefresh(dt, 60000, \'(Every 1 minute)\');\\n            }\\n        };\\n\\n        DataTable.ext.buttons.reload5minutes = {\\n\\n            text: function (dt) {\\n                return \'Every 5 minutes\';\\n            },\\n\\n            action: function (e, dt, button, config) {\\n                setAutorefresh(dt, 300000, \'(Every 5 minutes)\');\\n            }\\n        };\\n\\n        DataTable.ext.buttons.reload10minutes = {\\n\\n            text: function (dt) {\\n                return \'Every 10 minutes\';\\n            },\\n\\n            action: function (e, dt, button, config) {\\n                setAutorefresh(dt, 600000, \'(Every 10 minutes)\');\\n            }\\n        };\\n\\n        DataTable.ext.buttons.reload30minutes = {\\n\\n            text: function (dt) {\\n                return \'Every 30 minutes\';\\n            },\\n\\n            action: function (e, dt, button, config) {\\n                setAutorefresh(dt, 1800000, \'(Every 30 minutes)\');\\n            }\\n        };\\n\\n        DataTable.ext.buttons.custom = {};\\n    })(jQuery, jQuery.fn.dataTable);\\n    $.fn.dataTable.Buttons.defaults.dom.button.className = \'btn btn-sm\';\\n    $.fn.dataTable.ext.errMode = \'none\';\\n<\\/script>\\n<script src=\\\"https:\\/\\/www.fwunlock.net\\/js\\/script.js?v=1.0.61\\\" type=\\\"text\\/javascript\\\"><\\/script>\\n<script type=\\\"text\\/javascript\\\">\\n    $(document).on(\'submit\', \'form\', function (event) {\\n        event.preventDefault();\\n        let inp