dropmenu.removeAttr(\'style\');\\n    });\\n\\n    $(document).on(\'click\', function () {\\n        \\/\\/ Necessary to remove class each time so we don\'t unwantedly use dropup\'s offset top\\n        $(\'.dropup\').removeClass(\'dropup\');\\n    });\\n\\n    \\/\\/ Select2 defaults\\n    $.fn.select2.defaults.set(\\\"width\\\", \\\"100%\\\");\\n\\n    function initSelect(obj, force) {\\n\\n        let options = {\\n            theme: \\\"bootstrap\\\",\\n            placeholder: \'Choose\',\\n            language: {\\n                noResults: function () {\\n                    return \'No results found\';\\n                },\\n                searching: function () {\\n                    return \'Searching...\';\\n                }\\n            },\\n            allowClear: true\\n        }\\n\\n        if (obj.attr(\'data-source\') != undefined) {\\n            options.ajax = {\\n                delay: 250,\\n                url: obj.attr(\'data-source\'),\\n                dataType: \'json\',\\n                data: function (params) {\\n                    let query = {\\n                        search: params.term,\\n                        page: params.page || 1\\n                    }\\n\\n                    return query;\\n                },\\n                processResults: function (data, params) {\\n                    return {\\n                        results: data.data,\\n                    };\\n                }\\n            };\\n\\n            options.templateSelection = function (option) {\\n                let html = option.html;\\n                return html == undefined ? option.text : $(\'<span>\' + html + \'<\\/span>\');\\n            }\\n\\n            options.templateResult = function (option) {\\n                let html = option.html;\\n                return html == undefined ? option.text : $(\'<span>\' + html + \'<\\/span>\');\\n            }\\n\\n        } else {\\n\\n            options.templateSelection = function (option) {