INSERT INTO `remote_imei_services` (`id`, `api_provider_id`, `remote_id`, `name`, `group_name`, `price`, `time`, `info`, `min_qty`, `max_qty`, `network`, `mobile`, `provider`, `pin`, `kbh`, `mep`, `prd`, `type`, `locks`, `reference`, `udid`, `serial`, `secro`, `credit_groups`, `additional_fields`, `additional_data`, `params`, `created_at`, `updated_at`) VALUES
(2960, 2, '1267', 'USA Metro PCS/T-Mobile Unlock App by IMEI - Motorola / Revvl / Nokia / Alcatel / TCL Supported', 'Android Official App Unlocks', 5.0000, '1-5 Minutes', '<h2><span>1.  PLACE ORDER  (If you do not place the order first, the IMEI will be registered in a negative database and you will not be able to unlock it until the administrator enables that IMEI.)<br /><br /></span><span><span></span></span></h2>\r\n<h2><span>2. FOLLOW THE STEPS OF  THE TUTORIAL (OR AS WRITTEN BELLOW)</span><span><span></span></span></h2>\r\n<p><a href=\"https://www.youtube.com/watch?v=DN3YFPhq6GU&amp;feature=youtu.be\">https://www.youtube.com/watch?v=DN3YFPhq6GU&amp;feature=youtu.be</a></p>\r\n<h3>1 Connect to Wi-Fi.</h3>\r\n<h3>2 In that network, click on the settings to set the proxy and manual port and save.  ( PROXY 178.156.151.246  - PORT 8080 )</h3>\r\n<h3>3 Open this url in the browser https://mitm.it/cert/cer and it will download a file.</h3>\r\n<h3>4 Go to settings and in the magnifying glass type cert</h3>\r\n<h3>5 Select CA certificate, install anyway, select the cert and install.</h3>\r\n<h3>6 Go to settings, applications, Show system, look for the Unlock App at the end and delete the data.</h3>\r\n<h3>7 Go back, look for the Device Unlock option, click on it, it will give 1 error, select Permanent Unlock and Done (Unlocked 100%)</h3>\r\n<p></p>\r\n<p><strong>COMPATIBLE WITH MOST BRAND MODELS  </strong><span><span></span></span></p>\r\n<p><span>MOTOROLA / REVVL / LG / NOKIA / TCL / ALCATEL</span><span><span></span></span></p>\r\n<p><span>Metro and T-Mobile only</span></p>\r\n<p></p>\r\n<p><strong>EXAMPLE OF COMPATIBLE TESTED MODELS -100% TESTED</strong><span><span></span></span></p>\r\n<p><span>WTRVL5G    REVVL V+ 5G</span></p>\r\n<p><span>TMRV065G  REVVL 6X 5G T-MOBILE  </span></p>\r\n<p><span>TMRV075G  REVVL 7   T-MOBILE -INSERT SIMCARD</span></p>\r\n<p><span>motorola edge (2022)</span></p>\r\n<p><span>moto g 5G (2022)</span></p>\r\n<p><span>moto g 5G - 2023</span>