INSERT INTO `remote_server_services` (`id`, `api_provider_id`, `remote_id`, `name`, `group_name`, `price`, `time`, `info`, `min_qty`, `max_qty`, `credit_groups`, `additional_fields`, `additional_data`, `params`, `created_at`, `updated_at`) VALUES
(1197, 2, '209', 'Octoplus LG 1 Year Digital License', 'Gsm Server Products', 65.0000, NULL, '<p><strong>Octoplus LG 1 Year Digital License</strong>&nbsp;allows you to service LG phones.</p>\r\n<div class=\"yt-video -inside-dom\" data-video-id=\"SdbX7W2oWWs\" data-width=\"560\" data-height=\"315\">\r\n<div class=\"yt-video_container\">\r\n<h2 data-id=\"0-general-information\">General Information:</h2>\r\n<ul>\r\n<li>This license will be bound to your PC. No dongle or box is required.</li>\r\n<li>You can change a PC once per 48 hours (not more than 25 times during 1 year).</li>\r\n<li>The same license can be used on 2 PCs without switching limits.</li>\r\n<li>After the end of 1 Year period you will have to buy this license again.</li>\r\n</ul>\r\n<h2 data-id=\"1-main-features\">Main Features:</h2>\r\n<ul>\r\n<li>Decode</li>\r\n<li>Repair IMEI/Bluetooth</li>\r\n<li>Write Firmware</li>\r\n<li>Read/Calculate Codes</li>\r\n<li>Read/Write Full Flash</li>\r\n<li>Read/Write GDFS</li>\r\n<li>Flash via USB</li>\r\n<li>Read/Write/Repair NVM</li>\r\n<li>Read/Write/Repair EEPROM</li>\r\n<li>Edit Language</li>\r\n<li>Format FS</li>\r\n<li>Write/Repair Security</li>\r\n<li>Write Security Backup</li>\r\n<li>Factory Reset</li>\r\n<li>Hard Reset</li>\r\n<li>Read/Write/Repair TA</li>\r\n<li>Read Info</li>\r\n<li>Repair EFS</li>\r\n<li>Repair WiFi Address</li>\r\n<li>Reset Screen Lock/Pattern Lock</li>\r\n<li>Dump RAM/NAND</li>\r\n</ul>\r\n<h2 data-id=\"2-additional-features\">Additional Features:</h2>\r\n<ul>\r\n<li>LG Qualcomm language packs editor</li>\r\n<li>Writing firmware *.m0 files</li>\r\n<li>Flashing FullFlash binary files</li>\r\n<li>Flashing firmware *.ssw files</li>\r\n<li>Single-file flashing</li>\r\n<li>Read/write EEPROM</li>\r\n<li>Read/write NVM</li>\r\n<li>IMEI repair</li>\r\n<li>Fast country change</li>\r\n<li>Calibration data restore</li>\r\n<li>Format FFS</li>\r\n<li>Repair phone reset</li>\r\n</ul>\r\n<div class=\"widget_product_octopus-models\">\r\n<h2 data-id=\"