INSERT INTO `remote_server_services` (`id`, `api_provider_id`, `remote_id`, `name`, `group_name`, `price`, `time`, `info`, `min_qty`, `max_qty`, `credit_groups`, `additional_fields`, `additional_data`, `params`, `created_at`, `updated_at`) VALUES
(1200, 2, '210', 'Octoplus Samsung Digital 1 Year License', 'Gsm Server Products', 59.0000, NULL, '<p><strong>Octoplus Samsung 1 Year Digital License</strong>&nbsp;allows you to service Samsung cell phones.</p>\r\n<h2>General Information:</h2>\r\n<ul>\r\n<li>This license will be bound to your PC. No dongle or box is required.</li>\r\n<li>PC can be changed once per 48 hours (during the COVID-19 period)<br />When things will get back to normal, this time will be increased up to 72 hours.</li>\r\n<li>After the end of 1 year period you will have to buy this license again.</li>\r\n</ul>', NULL, NULL, NULL, '[]', '{\"SERVICEID\":210,\"SERVICENAME\":\"Octoplus Samsung Digital 1 Year License\",\"CREDIT\":\"59.0000\",\"INFO\":\"<p><strong>Octoplus Samsung 1 Year Digital License<\\/strong>&nbsp;allows you to service Samsung cell phones.<\\/p>\\r\\n<h2>General Information:<\\/h2>\\r\\n<ul>\\r\\n<li>This license will be bound to your PC. No dongle or box is required.<\\/li>\\r\\n<li>PC can be changed once per 48 hours (during the COVID-19 period)<br \\/>When things will get back to normal, this time will be increased up to 72 hours.<\\/li>\\r\\n<li>After the end of 1 year period you will have to buy this license again.<\\/li>\\r\\n<\\/ul>\",\"ADDITIONAL_NVP\":\"a:2:{s:13:\\\"hide_quantity\\\";i:0;s:13:\\\"quantity_rule\\\";a:4:{s:9:\\\"min_value\\\";s:0:\\\"\\\";s:9:\\\"max_value\\\";s:0:\\\"\\\";s:11:\\\"multiple_of\\\";s:0:\\\"\\\";s:9:\\\"specified\\\";s:0:\\\"\\\";}}\",\"TIME\":\"\",\"sync_key_data\":\"\",\"service_type_price_data\":\"\",\"qry_range_credit_info\":[{\"from_range\":1,\"to_range\":99,\"credit\":\"59.0000\"}],\"REQUIRED\":\"\"}', '{\"CUSTOM\":null}', '2026-02-25 03:00:52', '2026-02-25 03:00:52'),
